import{_ as t,o as a,c as i,a5 as s}from"./chunks/framework.UjrY2eRK.js";const k=JSON.parse('{"title":"Self-hosting with Bun, SQLite, and Docker","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/self-hosting/index.md","filePath":"deployment/self-hosting/index.md","lastUpdated":1788123021000}'),n={name:"deployment/self-hosting/index.md"};function o(r,e,d,l,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="self-hosting-with-bun-sqlite-and-docker" tabindex="-1">Self-hosting with Bun, SQLite, and Docker <a class="header-anchor" href="#self-hosting-with-bun-sqlite-and-docker" aria-label="Permalink to &quot;Self-hosting with Bun, SQLite, and Docker&quot;">​</a></h1><p>The supported self-hosted topology is one Linux container and one SQLite database on local persistent storage. The same Matrix and FCM contract runs on Cloudflare Workers and Bun; horizontal replicas, network filesystems, built-in TLS, outbound proxies, custom certificate authorities, and client development are outside this deployment.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Docker Engine with Docker Compose.</li><li>AMD64 or ARM64 Linux.</li><li>A Firebase project and compatible Android and iOS app IDs controlled by the Gateway Operator.</li><li>Direct CA-validated HTTPS access to Google OAuth and FCM.</li><li>A TLS reverse proxy on the host or the same private Docker network.</li></ul><p>Production deployments should pin <code>TRINITY_PUSH_GATEWAY_VERSION</code> to an immutable <code>vX.Y.Z</code> tag or image digest. <code>latest</code> is a quick-start convenience, not an upgrade policy.</p><h2 id="configure-secrets" tabindex="-1">Configure secrets <a class="header-anchor" href="#configure-secrets" aria-label="Permalink to &quot;Configure secrets&quot;">​</a></h2><p>Copy <code>.env.self-host.example</code> to an ignored environment file and set both app IDs. Create an operator-protected <code>secrets</code> directory containing four non-empty files:</p><ul><li><code>fcm_client_email</code></li><li><code>fcm_private_key</code>, containing the complete PEM</li><li><code>fcm_project_id</code></li><li><code>fingerprint_key</code>, containing an independent value of at least 32 bytes</li></ul><p>The supplied Compose service mounts these values through Docker secrets and starts Bun with automatic <code>.env</code> loading disabled. Direct <code>TRINITY_PUSH_GATEWAY_FCM_CLIENT_EMAIL</code>, <code>TRINITY_PUSH_GATEWAY_FCM_PRIVATE_KEY</code>, <code>TRINITY_PUSH_GATEWAY_FCM_PROJECT_ID</code>, and <code>TRINITY_PUSH_GATEWAY_FINGERPRINT_KEY</code> values remain available for controlled development. Setting a direct value and its <code>_FILE</code> alternative together is an error. All runtime inputs use the <code>TRINITY_PUSH_GATEWAY_</code> namespace; unprefixed legacy names are rejected.</p><h2 id="start-and-verify" tabindex="-1">Start and verify <a class="header-anchor" href="#start-and-verify" aria-label="Permalink to &quot;Start and verify&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --show-error</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health</span></span></code></pre></div><p>The image runs as UID/GID 1000 with a read-only root filesystem. The named <code>gateway-data</code> volume is the only persistent writable location. Operators replacing it with a bind mount must prepare that directory for UID/GID 1000 before startup.</p><p>Expected health response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;current package version&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Health validates configuration, storage access, and the current schema without contacting FCM or exposing internal details. Startup applies forward-only migrations and exits on migration, schema, or integrity failure before opening the HTTP listener.</p><h2 id="tls-and-source-addresses" tabindex="-1">TLS and source addresses <a class="header-anchor" href="#tls-and-source-addresses" aria-label="Permalink to &quot;TLS and source addresses&quot;">​</a></h2><p>Compose binds plain HTTP to <code>127.0.0.1:3000</code> by default; <code>TRINITY_PUSH_GATEWAY_HOST_PORT</code> changes the loopback port while <code>TRINITY_PUSH_GATEWAY_PORT</code> changes the Bun listener and container target port. Place Caddy, nginx, Traefik, or an equivalent TLS proxy in front of it. The proxy must replace untrusted forwarded-address input.</p><p>For a host proxy, a minimal Caddy route is:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>push.example.com {</span></span>
<span class="line"><span>  reverse_proxy 127.0.0.1:3000</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>For nginx, replace rather than append the client header:</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:3000;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    proxy_set_header </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">X-Forwarded-For $remote_addr;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>For Traefik or another proxy on the same Docker network, remove the host <code>ports</code> mapping, expose port 3000 only to that network, and configure the proxy&#39;s trusted forwarded-header networks.</p><p>By default the gateway rate-limits the direct peer. To use a forwarded address, set every direct proxy network in <code>TRINITY_PUSH_GATEWAY_TRUSTED_PROXY_CIDRS</code> and choose <code>TRINITY_PUSH_GATEWAY_CLIENT_IP_HEADER=x-forwarded-for</code> or <code>cf-connecting-ip</code>. Invalid, ambiguous, or entirely trusted chains share the fail-closed <code>unknown-source</code> key.</p><h2 id="runtime-configuration" tabindex="-1">Runtime configuration <a class="header-anchor" href="#runtime-configuration" aria-label="Permalink to &quot;Runtime configuration&quot;">​</a></h2><p>The Bun deployment defaults to:</p><table tabindex="0"><thead><tr><th>Setting</th><th style="text-align:right;">Default</th></tr></thead><tbody><tr><td><code>TRINITY_PUSH_GATEWAY_HOST</code></td><td style="text-align:right;"><code>0.0.0.0</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_PORT</code></td><td style="text-align:right;"><code>3000</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_DATABASE_PATH</code></td><td style="text-align:right;"><code>/data/gateway.sqlite</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MIGRATIONS_PATH</code></td><td style="text-align:right;"><code>/app/migrations</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_BODY_BYTES</code></td><td style="text-align:right;"><code>65536</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_DEVICES</code></td><td style="text-align:right;"><code>49</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_DAILY_ATTEMPTS</code></td><td style="text-align:right;"><code>20000</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_PENDING_LEASE_SECONDS</code></td><td style="text-align:right;"><code>120</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_TERMINAL_RETENTION_SECONDS</code></td><td style="text-align:right;"><code>86400</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_UPSTREAM_TIMEOUT_SECONDS</code></td><td style="text-align:right;"><code>10</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_REQUEST_DEADLINE_SECONDS</code></td><td style="text-align:right;"><code>30</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_SOURCE_RATE_LIMIT</code></td><td style="text-align:right;"><code>300</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_SOURCE_RATE_PERIOD_SECONDS</code></td><td style="text-align:right;"><code>10</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_MAX_SOURCE_KEYS</code></td><td style="text-align:right;"><code>10000</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_CLEANUP_INTERVAL_SECONDS</code></td><td style="text-align:right;"><code>86400</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_CLIENT_IP_HEADER</code></td><td style="text-align:right;"><code>x-forwarded-for</code></td></tr><tr><td><code>TRINITY_PUSH_GATEWAY_TRUSTED_PROXY_CIDRS</code></td><td style="text-align:right;">empty</td></tr></tbody></table><p>Compose additionally defaults <code>TRINITY_PUSH_GATEWAY_HOST_PORT</code> to <code>3000</code>. It is a host-side publication setting and is not read by the Bun process.</p><p>The short source limiter is process-local and may reset on restart. The SQLite daily budget remains authoritative. SQLite uses strict bindings, WAL, full synchronous durability, foreign keys, and a five-second busy timeout. Keep the database, <code>-wal</code>, and <code>-shm</code> files together on local storage.</p><h2 id="observed-footprint" tabindex="-1">Observed footprint <a class="header-anchor" href="#observed-footprint" aria-label="Permalink to &quot;Observed footprint&quot;">​</a></h2><p>A development measurement on x86-64 Linux with Bun 1.4.0 used 35.2 MiB RSS after startup and 48.7 MiB RSS after a concurrent burst of 50 SQLite-coordinated notification requests. The resulting database was 20 KiB with the schema and 50 terminal delivery records. The automated Bun suite requires the same 50-request burst to finish in under two seconds; the observed local run completed in under 100 ms.</p><p>These figures are implementation evidence, not capacity guarantees. Allocator behavior, architecture, container accounting, traffic shape, retention, and Push Key size affect real memory and database growth. Operators should measure their own workload and alert on container memory, volume usage, <code>5xx</code> responses, and health failures.</p><h2 id="backup-and-restore" tabindex="-1">Backup and restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and restore&quot;">​</a></h2><p>Create a consistent online snapshot in a new file:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/backups:/backups&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/backups/gateway-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y%m%dT%H%M%SZ).sqlite&quot;</span></span></code></pre></div><p>Prepare the host backup directory for UID/GID 1000 and copy verified snapshots off-host. The command refuses to overwrite a file and verifies SQLite integrity before reporting success.</p><p>For a cold backup, stop the serving container first, then run the same snapshot command as the only process with the volume mounted:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gateway</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.self-host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-deps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/backups:/backups&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  gateway</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/backups/gateway-cold-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y%m%dT%H%M%SZ).sqlite&quot;</span></span></code></pre></div><p>Keep the gateway stopped until the command finishes. This makes the documented <code>VACUUM INTO</code> snapshot a cold backup without copying a live WAL file set.</p><p>For an offline restore, stop the gateway, preserve the current volume, replace the database only from a verified snapshot, and remove stale <code>gateway.sqlite-wal</code> and <code>gateway.sqlite-shm</code> files. Before resuming traffic, run <code>docker compose --env-file .env.self-host run --rm --no-deps gateway migrate</code>; opening the database executes <code>PRAGMA integrity_check</code>, then verifies or applies the expected migrations. Restart and require <code>/health</code> to become ready. Never copy only the main file from a live WAL database.</p><h2 id="upgrade-and-rollback" tabindex="-1">Upgrade and rollback <a class="header-anchor" href="#upgrade-and-rollback" aria-label="Permalink to &quot;Upgrade and rollback&quot;">​</a></h2><ol><li>Create and retain a verified backup.</li><li>Pin the new <code>vX.Y.Z</code> image or digest.</li><li>Run <code>docker compose pull</code> and <code>docker compose up --detach</code>.</li><li>Wait for healthy status and inspect redacted startup/migration logs.</li></ol><p>Migrations are expand-first and preserve a one-version rollback path. An additive migration that the preceding image can safely read declares <code>-- minimum-reader: &lt;previous migration filename&gt;</code> at the start of its SQL file. Incompatible migrations default to their own filename, so older images refuse them. To roll back, stop the new container, pin the immediately preceding stable image, recreate it, and verify health. The gateway refuses incompatible newer schemas and never downgrades automatically.</p><h2 id="operations-and-troubleshooting" tabindex="-1">Operations and troubleshooting <a class="header-anchor" href="#operations-and-troubleshooting" aria-label="Permalink to &quot;Operations and troubleshooting&quot;">​</a></h2><ul><li>Structured JSON logs go to stdout/stderr. They exclude Push Keys, Matrix identifiers, account routes, payloads, access tokens, and credentials.</li><li><code>429</code> means the short source limit or persistent daily budget was exhausted.</li><li><code>502</code> means OAuth or FCM was unavailable or timed out.</li><li><code>503</code> means configuration, storage, schema, or concurrent delivery was unavailable.</li><li>A full disk, SQLite busy timeout, I/O error, or runtime storage failure fails requests explicitly; the gateway never bypasses delivery coordination or budgets.</li><li>Rotate configuration and credentials by recreating the container. There is no live reload or HTTP administration endpoint.</li><li>On shutdown, the gateway rejects new work and drains in-flight requests for up to 30 seconds. At the ceiling, or after a second termination signal, it closes SQLite and explicitly terminates; Compose uses the same 30-second grace period.</li><li>Do not use an automatic container updater. Back up, upgrade, and verify explicitly.</li></ul>`,44)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
